def count_ham_cycles2(n, edges):
    start=0
    out=[0]*n
    inmask=[0]*n
    for u,v in edges:
        out[u]|=1<<v
        inmask[v]|=1<<u
    FULL=((1<<n)-1) ^ (1<<start)
    @lru_cache(None)
    def f(mask,v):
        # path start -> ... -> v using exactly vertices in mask (subset of non-start), with v in mask
        if mask==(1<<v):
            return 1 if (out[start]>>v)&1 else 0
        total=0
        prevmask=mask ^ (1<<v)
        m = inmask[v] & prevmask
        while m:
            b=m & -m
            u=b.bit_length()-1
            total += f(prevmask,u)
            m -= b
        return total
    total=0
    mask=FULL
    for v in range(1,n):
        if (out[v]>>start)&1:
            total += f(mask,v)
    return total, f.cache_info().currsize

