random.seed(201)

def count_ham_cycles(n, edges):
    start=0
    out=[0]*n
    inmask=[0]*n
    for u,v in edges:
        out[u]|=1<<v
        inmask[v]|=1<<u
    FULL=((1<<n)-1) ^ (1<<start)
    @lru_cache(None)
    def f(mask,v):
        if mask==(1<<v):
            return 1 if (out[start]>>v)&1 else 0
        prev=mask ^ (1<<v)
        total=0
        m=inmask[v] & prev
        while m:
            b=m & -m
            u=b.bit_length()-1
            total += f(prev,u)
            m -= b
        return total
    t=time.time()
    total=0
    for v in range(1,n):
        if (out[v]>>start)&1:
            total += f(FULL,v)
    dt=time.time()-t
    return total,dt,f.cache_info().currsize

for n,p,lo,hi in [(19,0.21,300000,2000000),(20,0.19,500000,3500000),(21,0.18,800000,5000000)]:
    for trial in range(300):
        edges=[]
