import random, time, sys
from functools import lru_cache
random.seed(400)

def count_linext(n, edges):
    pre=[0]*n
    for u,v in edges:
        pre[v] |= 1<<u
    FULL=(1<<n)-1
    @lru_cache(None)
    def dp(mask):
        if mask==FULL:
            return 1
        rem=FULL^mask
        total=0
        m=rem
        while m:
            b=m & -m
            i=b.bit_length()-1
            if pre[i] & ~mask == 0:
                total += dp(mask|b)
            m -= b
        return total
    t=time.time(); ans=dp(0); dt=time.time()-t
    return ans,dt,dp.cache_info().currsize

