lam=(13,12,10,8,7,5,4,2)
mu=(5,3,2,1)
m=10
mu_ext=list(mu)+[0]*(len(lam)-len(mu))
M=[]
for i in range(len(lam)):
    row=[]
    for j in range(len(lam)):
        r=lam[i]-mu_ext[j]-i+j
        row.append(0 if r<0 else comb(m+r-1,r))
    M.append(row)
ans=4671855102047735602000

def det_mod(M,p):
    A=[[x%p for x in row] for row in M]
    n=len(A)
    det=1
    for i in range(n):
        pivot=None
        for r in range(i,n):
            if A[r][i]%p:
                pivot=r; break
        if pivot is None:
            return 0
        if pivot!=i:
            A[i],A[pivot]=A[pivot],A[i]
            det=(-det)%p
        det=(det*A[i][i])%p
        inv=pow(A[i][i],-1,p)
        for r in range(i+1,n):
            if A[r][i]%p:
                fac=A[r][i]*inv%p
                for c in range(i,n):
                    A[r][c]=(A[r][c]-fac*A[i][c])%p
    return det%p
for p in [101,1009,10007,1000003]:
    print(p, det_mod(M,p), ans%p)
